use vstd::prelude::*;

verus! {

fn is_sorted(arr: &Vec<i32>) -> (result: bool)
    requires
        arr.len() > 0,
    ensures
        result
            == (forall|i: int, j: int|
                    0 <= i < j < arr@.len() ==>
                    arr@.index(i) <= arr@.index(j)),
{
    // n is the length of the array, as a mathematical integer
    let n: int = arr.len() as int;

    // idx ranges from 1 up to n
    let mut idx: int = 1;
    // so_far holds the property that all pairs (i, j) with 0 <= i < j < idx are in order
    let mut so_far: bool = true;

    while idx < n
        invariant
            // bounds on idx
            1 <= idx <= n,
            // so_far exactly characterizes sortedness up to idx
            so_far
                == (forall|i: int, j: int|
                        0 <= i < j < idx ==>
                        arr@.index(i) <= arr@.index(j)),
        decreases n - idx,
    {
        // Check the new adjacent pair (idx-1, idx)
        if so_far && arr[(idx - 1) as usize] <= arr[idx as usize] {
            // still sorted up to idx+1
            so_far = true;
        } else {
            // once false, remains false
            so_far = false;
        }
        idx = idx + 1;
    }

    // At termination, idx == n, so so_far == forall i<j<n arr[i] <= arr[j]
    so_far
}

}

